import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useLang } from '../App';

export default function TrainingPage() {
  const { lang } = useLang();
  const navigate = useNavigate();
  const token = localStorage.getItem('rnp_token');
  const headers = { Authorization: `Bearer ${token}` };

  const [questions, setQuestions] = useState([]);
  const [current, setCurrent] = useState(0);
  const [answers, setAnswers] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [finished, setFinished] = useState(false);
  const startTimeRef = useRef(new Date().toISOString());

  useEffect(() => {
    axios.get('/api/exam/training', { headers })
      .then(r => { setQuestions(r.data); setLoading(false); })
      .catch(err => { setError(err.response?.data?.message || 'Failed to load questions'); setLoading(false); });
  }, []);

  const selectAnswer = (questionId, option) => {
    setAnswers(prev => ({ ...prev, [questionId]: option }));
  };

  const finishTraining = () => {
    if (Object.keys(answers).length === 0) return;
    setFinished(true);
  };

  const getOptionClass = (q, opt) => {
    const selected = answers[q.id] === opt;
    const correct = q.correct_answer === opt;
    if (finished || selected) {
      if (correct) return 'correct';
      if (selected && !correct) return 'wrong';
    }
    if (selected) return 'selected';
    return '';
  };

  if (loading) return (
    <div style={{ minHeight:'100vh', display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', background:'#f0f4f8' }}>
      <div style={{fontSize:48, marginBottom:20}}>🦅</div>
      <div style={{color:'#1e293b', fontSize:18, fontWeight:700}}>{lang==='rw'?'Gutegura ibibazo...':'Loading questions...'}</div>
    </div>
  );

  if (error) return (
    <div style={{ minHeight:'100vh', display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', background:'#f0f4f8', padding:20 }}>
      <div style={{fontSize:48, marginBottom:16}}>⚠️</div>
      <p style={{color:'#dc2626', fontSize:16, fontWeight:600, marginBottom:16}}>{error}</p>
      <a href="/dashboard" style={{color:'#2563eb'}}>{lang==='rw' ? '← Garuka ku dashboard' : '← Back to Dashboard'}</a>
    </div>
  );

  const q = questions[current];
  const answeredCount = Object.keys(answers).length;

  const options = ['a', 'b', 'c', 'd'];
  const optionText = (opt) => {
    if (lang === 'en') return q[`option_${opt}_en`] || q[`option_${opt}_rw`];
    return q[`option_${opt}_rw`];
  };
  const questionText = lang === 'en' ? (q.question_en || q.question_rw) : q.question_rw;

  return (
    <div>
      <div style={{ background:'white', padding:'12px 20px', display:'flex', alignItems:'center', justifyContent:'space-between', boxShadow:'0 2px 8px rgba(0,0,0,0.08)', gap:12, flexWrap:'wrap' }}>
        <div style={{ display:'flex', alignItems:'center', gap:8, minWidth:120 }}>
          <span style={{fontSize:22}}>🦅</span>
          <span style={{ fontSize:12, fontWeight:700, color:'#0a1628' }}>RNP - {lang==='rw'?'Icyigisho':'Training'}</span>
        </div>
        <div style={{ display:'flex', gap:6, flexWrap:'wrap', justifyContent:'center' }}>
          {questions.slice(0, 10).map((q2, i) => (
            <div key={q2.id} className={`bubble ${i===current?'current': answers[q2.id]?'answered':'unanswered'}`} onClick={()=>setCurrent(i)} title={`Q${i+1}`}>{i+1}</div>
          ))}
          {questions.slice(10, 20).map((q2, i) => {
            const idx = i + 10;
            return <div key={q2.id} className={`bubble ${idx===current?'current': answers[q2.id]?'answered':'unanswered'}`} onClick={()=>setCurrent(idx)} title={`Q${idx+1}`}>{idx+1}</div>;
          })}
        </div>
        <div style={{ fontSize:13, color:'#64748b' }}>
          {answeredCount}/{questions.length} {lang==='rw'?'basubijwe':'answered'}
        </div>
      </div>

      <div style={{ flex:1, padding:'20px 16px', maxWidth:800, width:'100%', margin:'0 auto' }}>
        <div style={{ background:'white', borderRadius:12, padding:'24px', boxShadow:'0 2px 12px rgba(0,0,0,0.07)' }}>
          <div style={{ marginBottom:6 }}>
            <span style={{ fontSize:12, fontWeight:700, color:'#2563eb', textTransform:'uppercase', letterSpacing:'0.5px' }}>
              {lang==='rw' ? 'Ikibazo' : 'Question'} {current+1} / {questions.length}
            </span>
          </div>
          <p style={{ fontSize:16, fontWeight:600, color:'#1e293b', lineHeight:1.6, marginBottom:20, marginTop:8 }}>{questionText}</p>
          <div>
            {options.map(opt => (
              <div key={opt} className={`option-row ${getOptionClass(q, opt)}`} onClick={()=>selectAnswer(q.id, opt)}>
                <div className="option-letter">{opt}</div>
                <span style={{ fontSize:14, color:'#374151', lineHeight:1.5 }}>{optionText(opt)}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div style={{ background:'white', padding:'12px 20px', display:'flex', alignItems:'center', justifyContent:'space-between', boxShadow:'0 -2px 8px rgba(0,0,0,0.06)', gap:12, flexWrap:'wrap' }}>
        <button className="btn-orange" onClick={finishTraining} disabled={answeredCount===0} style={{ minWidth:160 }}>
          {finished ? (lang==='rw'?'Mwarangiye':'Finished') : (lang==='rw'?'Soza icyigisho':'Finish Training')}
        </button>
        <div style={{ display:'flex', gap:10 }}>
          <button className="btn-orange" onClick={()=>setCurrent(c=>Math.max(0,c-1))} disabled={current===0}>
            {lang==='rw' ? '◀ Icyabanje / Previous' : '◀ Previous'}
          </button>
          <button className="btn-orange" onClick={()=>setCurrent(c=>Math.min(questions.length-1,c+1))} disabled={current===questions.length-1}>
            {lang==='rw' ? 'Igikurikira / Next ▶' : 'Next ▶'}
          </button>
        </div>
      </div>

      {finished && (
        <div style={{ position:'fixed', inset:0, background:'rgba(0,0,0,0.6)', display:'flex', alignItems:'center', justifyContent:'center', zIndex:1000 }}>
          <div className="modal-box">
            <h3>📚 {lang==='rw'?'Icyigisho cyarangiye':'Training Finished'}</h3>
            <p>{lang==='rw' ? `Wabusubije ${answeredCount} muri ${questions.length}` : `You answered ${answeredCount} out of ${questions.length}`}</p>
            <div className="modal-actions">
              <button className="btn-outline" onClick={()=>{ setFinished(false); setAnswers({}); setCurrent(0); startTimeRef.current = new Date().toISOString(); }}>
                {lang==='rw'?'Ongera':'Try Again'}
              </button>
              <button className="btn-blue" onClick={()=>navigate('/dashboard')}>{lang==='rw'?'Garuka ku dashboard':'Back to Dashboard'}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
